const input = $json; const session = Array.isArray(input) && input.length > 0 ? input[0] : null;
if (!session || !session.step) {
  return [{json: {...input, reply: 'Menu router', action: null, session: null}}];
}
const step = session.step;
const td = session.temp_data ? JSON.parse(typeof session.temp_data === 'string' ? session.temp_data : '{}') : {};
const phone = session.phone;
const msg = input.message;
const instance = input.instance;
const ps = {
  'awaiting_full_name': '👤 Nombre completo:',
  'awaiting_email': '📧 Email:',
  'awaiting_username': '🔑 Username:',
  'awaiting_password_choice': '🔐 Contraseña?\n1 - Automatica\n2 - Manual',
  'awaiting_password_manual': '✏️ Escribe la contraseña:',
  'awaiting_tenant_id_view': '🔍 ID del tenant:',
  'awaiting_tenant_id_edit': '✏️ ID del tenant a editar:',
  'awaiting_edit_fields': '✏️ Campos JSON (full_name, email, phone):',
  'awaiting_tenant_id_deactivate': '⛔ ID del tenant a desactivar:',
  'awaiting_tenant_id_reactivate': '✅ ID del tenant a reactivar:',
  'awaiting_tenant_id_delete': '🗑️ ID del tenant a eliminar:'
};
// Handle each step
if (step === 'awaiting_full_name') {
  td.full_name = msg;
  return [{json: {phone, instance, reply: ps.awaiting_email, step: 'awaiting_email', temp_data: JSON.stringify(td), action: null}}];
}
if (step === 'awaiting_email') {
  td.email = msg;
  return [{json: {phone, instance, reply: ps.awaiting_username, step: 'awaiting_username', temp_data: JSON.stringify(td), action: null}}];
}
if (step === 'awaiting_username') {
  td.username = msg;
  return [{json: {phone, instance, reply: ps.awaiting_password_choice, step: 'awaiting_password_choice', temp_data: JSON.stringify(td), action: null}}];
}
if (step === 'awaiting_password_choice') {
  if (msg === '1') {
    const payload = {full_name: td.full_name, email: td.email, username: td.username};
    return [{json: {phone, instance, reply: '✅ Creando tenant...', action: 'create_tenant', create_payload: JSON.stringify(payload), step: null, temp_data: null}}];
  } else {
    td.password_choice = 'manual';
    return [{json: {phone, instance, reply: ps.awaiting_password_manual, step: 'awaiting_password_manual', temp_data: JSON.stringify(td), action: null}}];
  }
}
if (step === 'awaiting_password_manual') {
  const payload = {full_name: td.full_name, email: td.email, username: td.username, password: msg};
  return [{json: {phone, instance, reply: '✅ Creando tenant...', action: 'create_tenant', create_payload: JSON.stringify(payload), step: null, temp_data: null}}];
}
const singleStepActions = {
  'awaiting_tenant_id_view': {action: 'get_tenant'}, 'awaiting_tenant_id_deactivate': {action: 'deactivate_tenant'}, 'awaiting_tenant_id_reactivate': {action: 'reactivate_tenant'}, 'awaiting_tenant_id_delete': {action: 'delete_tenant'}
};
if (singleStepActions[step]) {
  return [{json: {phone, instance, reply: 'Procesando...', action: singleStepActions[step].action, tenant_id: msg, step: null, temp_data: null}}];
}
if (step === 'awaiting_tenant_id_edit') {
  td.tenant_id = msg;
  return [{json: {phone, instance, reply: ps.awaiting_edit_fields, step: 'awaiting_edit_fields', temp_data: JSON.stringify(td), action: null}}];
}
if (step === 'awaiting_edit_fields') {
  return [{json: {phone, instance, reply: 'Editando...', action: 'edit_tenant', tenant_id: td.tenant_id, edit_payload: msg, step: null, temp_data: null}}];
}
return [{json: {phone, instance, reply: 'Menu router', action: null, session: null}}];

const p = $json; const action = p.action; const status = p.statusCode || 200; const data = p.data || p;
const create_resp = status >= 200 && status < 300 && data ? `✅ Tenant creado: ${data.full_name || ''}\nUsuario: ${data.username || ''}\nID: ${String(data.id || '').substring(0,8)}...` : `❌ Error: ${p.detail || p.message || 'Error desconocido'}`;
const view_resp = status >= 200 && status < 300 && data ? `📋 ${data.full_name || ''}\nEmail: ${data.email || '-'}\nTel: ${data.phone || '-'}\nUsuario: ${data.username || '-'}\nEstado: ${data.is_active ? '✅ Activo' : '⛔ Inactivo'}` : `❌ Error: ${p.detail || 'No encontrado'}`;
const edit_resp = status >= 200 && status < 300 ? `✅ Tenant actualizado correctamente` : `❌ Error: ${p.detail || 'Error al actualizar'}`;
const deactivate_resp = status >= 200 && status < 300 ? `⛔ Tenant desactivado correctamente` : `❌ Error: ${p.detail || 'No se pudo desactivar'}`;
const reactivate_resp = status >= 200 && status < 300 ? `✅ Tenant reactivado correctamente` : `❌ Error: ${p.detail || 'No se pudo reactivar'}`;
const delete_resp = status >= 200 && status < 300 ? `🗑️ Tenant eliminado correctamente` : `❌ Error: ${p.detail || 'No se pudo eliminar'}`;
const map = {create_tenant: create_resp, get_tenant: view_resp, edit_tenant: edit_resp, deactivate_tenant: deactivate_resp, reactivate_tenant: reactivate_resp, delete_tenant: delete_resp};
return [{json: {phone: p.phone, instance: p.instance, reply: map[p.action] || '✅ Operacion completada', session: null}}];
